text:
{
  "title": "سياسة الاستخدام والخصوصية لمنصة تبيان الرقمية",
  "planted": [
    {
      "slot": "p1",
      "text": "في حال وقوع أي اختراق أمني أو وصول غير مصرح به للبيانات، تحتفظ الشركة بالحق المطلق والتقديري الكامل في تقييم الموقف وتحديد ما إذا كان إشعار الجهات المختصة أو المستخدمين المتضررين ملائماً للظروف، ودون الالتزام بأي أطر زمنية محددة؛ كما لا يحمل أي طرف معالج للبيانات التزاماً بالإبلاغ الفوري عن تلك الحوادث."
    },
    {
      "slot": "p2",
      "text": "تلتزم المنصة بإتاحة هذه السياسة للمستخدمين قبل الشروع في جمع البيانات الشخصية، بحيث توضح بدقة أغراض الجمع، وأنواع البيانات، وآليات المعالجة والتخزين والتدمير، إضافة إلى بيان حقوق أصحاب البيانات وكيفية ممارستها عملياً."
    },
    {
      "slot": "p3",
      "text": "يتم الاحتفاظ بالبيانات المدخلة للمدة الزمنية التي تتطلبها الأغراض التشغيلية للمنصة، على أن تتم مراجعة الحاجة لاستمرار الاحتفاظ بها دورياً واتخاذ الإجراءات المناسبة بشأنها وفقاً للمتطلبات التجارية والتشغيلية القائمة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية ورسوم الاشتراك المطبقة للتسعير الموضح في صفحة الأسعار الرسمية للمنصة، وتكون جميع المدفوعات غير قابلة للاسترداد بعد اتمام عملية المعالجة بنجاح.",
    "تظل حقوق الملكية الفكرية المتعلقة بالتصميمات والعلامات التجارية والبرمجيات الخاصة بالمنصة مملوكة حصرياً للشركة، ولا يحق لأي طرف استخدامها دون إذن خطي مسبق.",
    "تبدأ هذه الاتفاقية تاريخ تفعيل الحساب وتستمر حتى قيام أحد الطرفين بإنهاء الخدمة وفقاً لآليات الإلغاء المتاحة عبر لوحة التحكم.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو خسارة الأرباح الناتجة عن تعطل الخدمة المؤقت بسبب أعمال الصيانة أو القوة القاهرة.",
    "تخضع هذه الشروط وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص المحاكم المختصة بالفصل في أي نزاع قد ينشأ عنها.",
    "تعتبر كافة الإشعارات والمراسلات المتبادلة بين الطرفين صحيحة ومنتجة لآثارها القانونية إذا تم إرسالها عبر البريد الإلكتروني المسجل في الحساب أو من خلال الإشعارات الداخلية للمنصة."
  ]
}
